  'con.prompt.kagome': "Kagome star: it emerged from {n} cells, six lines in three directions. Around it, the Kagome lattice. Tap on: Z rises into pyrochlore.",
  'con.prompt.tt': "Truncated tetrahedron: Kagome’s hexagon in 3D, the body: four hexagons, four triangles. Now its limbs: a tetrahedron on each triangle, all four in one tap.",
  'con.prompt.pyrochlore': "Pyrochlore: {n} cells, the truncated tetrahedron with a tetrahedron on each triangle: one big tetrahedron, 3D+’s Pyrochlore piece. Around it, the pyrochlore lattice. Tap on: W rises into hyper-pyrochlore.",
  'con.prompt.t5': "Truncated 5-cell: the body in 4D, five truncated tetrahedra (yours one) and five tetrahedra. Now its limbs, all five in one tap.",
