  'con.prompt.rdBody': "Cube: the RD’s body, inside it; its edges are the rhombi’s short diagonals. Now its limbs: a pyramid on each face, all six in one tap.",
  'con.prompt.rd': "Rhombic dodecahedron: the cube with its six pyramids, twelve rhombi, {n} cells. Around it, the twelve RDs of its lattice. Tap on: W splits its corners apart.",
  'con.prompt.rdTesseract': "Tesseract: the RD’s cube, its corners split apart in W, the body in 4D. Now its limbs: the six apexes join both sides in one tap, then two more out along W in another.",
