  // ---- Kaleidohedra's own (joined 2026-10-08): its worlds' strings, and its versions of shared keys ----
  'wiz.3d.icosa': "DICTO's icosahedral family, one shape at a time: the Lotus seed, UNITY, the DICTO Stella-Corona and the Kepler Star Diadem with their pieces. Pull them apart to see how they fit.",
  'icosa.shape': "Shape",
  'icosa.clusters': "Clusters",
  'icosa.pieces': "Pieces",
  'icosa.view': "View",
  'icosa.view.pieces': "All pieces",
  'icosa.view.build': "DICTO's build (63)",
  'icosa.view.units': "Hasu units",
  'icosa.apart': "Pull apart",
  'icosa.fill.off': "Fill gaps: off",
  'icosa.fill.on': "Fill gaps: on (120 Shark Teeth)",
  'icosa.note.LOTUS_SEED': "A regular icosahedron of edge φ², cut exactly into 12 icosahedra, a small one and the gap pieces AXE, FUJI and CLEO. Views: 113 pieces; DICTO's own build, a dodecahedron + 12 J11 + 30 AXE + 20 FUJI; or 12 Hasu units round the centre (#19).",
  'icosa.note.UNITY': "DICTO's 13-cell: an icosidodecahedron with a J11 on each pentagon; the 12 J11 touch only at its 30 corners (#19).",
  'icosa.note.VENUS': "UNITY with its 20 dimples closed by VAJRA (#19).",
  'icosa.note.STELLA_CORONA': "An icosidodecahedron, 20 icosahedra on its triangles and 12 King of Pentacles on its pentagons: 33 pieces, closed, every contact a whole face. The DICTO-Star's icosahedral twin (#20).",
  'icosa.note.KEPLER_STAR_DIADEM': "The DICTO Stella-Corona with a Kepler Star on every pentagram. Fill gaps adds the 120 Shark Teeth (60 mirror pairs) that close its thin crevices (#20).",
  'icosa.note.DESHI': "12 icosahedra on a dodecahedron's pentagons round a small icosahedron, sharing 30 edges. The arrangement is R. W. Gray's (2002) (#19).",
  'icosa.note.TWELVE_STAR_VOIDS': "An icosidodecahedron with an icosahedron on each of its 20 triangles. The 20-icosahedron shell is the Wolfram Demonstration \"Cluster of 20 Icosahedra\" (#20).",
  'icosa.note.KEPLER_MACE': "Two DICTO Stella-Coronas joined through one Kepler Star along a five-fold axis: the bond of the MACE network (#20).",
  'icosa.note.AXE': "Gap piece: five edges 1, one edge 1/φ, volume 1/12. It fills the gap two icosahedra leave round an edge. The Mosseri–Sadoc tile t6 at scale 1/τ (Mosseri & Sadoc 1982).",
  'icosa.note.FUJI': "Gap piece: a hexagonal pyramid at each outer corner of the Lotus seed, volume (1 + 3√5)/24.",
  'icosa.note.CLEO': "Gap piece: a slim tetrahedron at each inner corner of the Lotus seed. The Mosseri–Sadoc tile t4 at scale 1/τ (Mosseri & Sadoc 1982).",
  'icosa.note.TRISKELION': "CLEO with its 3 inner AXE, as one piece.",
  'icosa.note.TRISKELION_HEX': "FUJI with its 3 AXE, as one piece.",
  'icosa.note.INNER_EYE': "The space the Lotus seed's 12 outer icosahedra enclose: a dodecahedron minus its 12 caps.",
  'icosa.note.HASU': "One outer icosahedron with its fins: 12 of these and the small centre make the Lotus seed, each lifting straight out.",
  'icosa.note.VAJRA': "The convex piece that closes one of UNITY's dimples.",
  'icosa.note.HMV': "A J2 cap with 5 AXE and 5 CLEO: what fills a pentagonal dimple of the Stella-Corona.",
  'icosa.note.FIVE_OF_CUPS': "HMV (Gramophone) as one convex piece.",
  'icosa.note.KING_OF_PENTACLES': "HMV with its outer ring of AXE, flat pentagram on top: one on each pentagon of the Stella-Corona.",
  'icosa.note.HOUND_TOOTH': "Gap piece: the Mosseri–Sadoc tile t2 at scale 1/τ (Mosseri & Sadoc 1982), fitting between a pentagram triangle and a small icosidodecahedron.",
  'icosa.note.TRICAP': "Gap piece: the Mosseri–Sadoc tile t3 at scale 1/τ (Mosseri & Sadoc 1982), a flat pyramid over a unit triangle.",
  'icosa.note.KEPLER_STAR': "Kepler's small stellated dodecahedron (1619) at scale 1/φ, minus the spike on its base: it sits on a King of Pentacles' pentagram along whole faces.",
  'icosa.note.SHARK_TOOTH': "The piece cut to fill the Kepler Star Diadem's 26.06° crevices (not golden): 120 of them, in mirror pairs.",
  'icosa.note.BERMUDA_PYRAMID': "The piece cut to fill the 63.43° gap beside a small dodecahedron (not golden).",
  'wiz.3d.studies': "One solid at a time, built exactly from the Euclid–Kepler–Pacioli cell: the windows, their morphs and the stretched dodecahedron. Shear them as copies or as the solid itself.",
  'shear.gap': "Red band: here the cell no longer fills space (its volume is not the lattice's cell volume). Cell 0 always does.",
