  'kept.check.unavailable': "cannot be regenerated by this version",
  'studies.study': "Study",
  'studies.windows': "Windows: dodecahedron minus six stellas",
  'studies.windowsStellas': "Windows, with the six stellas",
  'studies.checker': "Windows and stellas, checkerboard",
  'studies.apart': "Apart",
  'studies.note.checker': "The stella octangula is the windows' other half: windows in the even cells, stellas in the odd ones, and each odd cube is its stella plus its six neighbours' carved roofs, with no gap or overlap. Volumes 12 + 4 = two cubes. Pull them apart to see them fit.",
  'studies.dogstar': "Dodecahedra and their Dogstars",
  'studies.note.dogstar': "Regular dodecahedra on the even cells (their densest lattice packing) leave one hole in each odd cell, and the hole is exactly a Dogstar: a partial stellation of a dodecahedron 1/φ³ their size (its core, all 12 pyramids, 24 of 30 wedges and the 8 spikes pointing at the cube corners), inside the cell's stella octangula. Its edges are only 2/φ⁴, 2/φ³, 2/φ² and 2/φ. Dodecahedra and Dogstars fill space; pull them apart to see. The Dogstar is George W. Hart's stellation 8 of the dodecahedron (1996), which he noted fills space alternated with regular dodecahedra; Polyhedra-World also shows it. Hans Walser describes it too, as a cube with its six hip roofs cut away (his “semi-regular dodecahedron”), which fills space with regular dodecahedra like a 3D chessboard.",
  'studies.stretch': "Stretched dodecahedron",
  'studies.slider.stretch': "Stretch",
  'studies.shear.copies': "Shear: copies on the lattice",
  'studies.shear.solid': "Shear: the solid itself",
  'studies.expanded': "Windows made convex (pushed out)",
  'studies.push': "Push",
  'studies.note.expanded': "Each rhombus pushed straight out, same size and angle; the hull. At the golden push (0.727) the gaps over the cube faces flatten into 6 golden rhombi: 12 thick rhombi, 6 golden rhombi, 8 equilateral triangles, 48 triangles.",
  'studies.icosido': "Windows into the icosidodecahedron",
  'studies.morph': "Morph",
  'studies.note.icosido': "Each rhombus slides out along its normal and across its own plane, keeping its size and 72° shape. At the end their hull is the icosidodecahedron (12 regular pentagons, 20 equilateral triangles): each rhombus lies in a pentagon, which is a 72° rhombus plus a golden triangle.",
  'studies.rdMorph': "Windows into the rhombic dodecahedron",
  'studies.note.rdMorph': "Each window keeps its cube edge (its long diagonal) and swings and stretches its other diagonal about it, through squares, until the 12 close up exactly as the rhombic dodecahedron, whose rhombi have the cube edge as their short diagonal.",
  'studies.note.windows': "12 rhombi of 72° and 108°, each in the dodecahedron's own face plane on a cube edge; the cut-away is 48 triangles. Volume exactly 12.",
  'studies.note.windowsStellas': "12 rhombi of 72° and 108°, each in the dodecahedron's own face plane on a cube edge; the cut-away is 48 triangles. Volume exactly 12.",
  'studies.note.stretch': "8 regular pentagons, 4 hexagons, 2 rectangles at any stretch; squares at one edge (1.236); two face-neighbours' hull at 2.",
  'wiz.3d.targets': "The 160 target cells: every space-filling cell with all edges equal whose edges meet only at special angles. Pick one to see it alone, with its face neighbours, or as a block of its lattice.",
