  'pv.detail.zomeCredit': "Found by DICTO in Zometool, built from medium blue struts: every edge runs along one of Zome's blue directions.",
  'pv.detail.bainCredit': "From the Bain stretch: stretch a body-centred cubic lattice by √2 along one axis and it becomes face-centred cubic. These are the cells of that stretch with every edge equal, found and checked in Kaleidohedra by DICTO. The rhombic dodecahedron form was already known, and so was the regular-hexagon elongated dodecahedron (the truncated octahedron with one zone removed), which DICTO reached independently by this new route; the other elongated dodecahedron was found by DICTO.",
  'pv.detail.regularNineCredit': "One of the Kaleidohedra Regular 9: the only space-fillers with every edge equal whose faces are all squares, regular hexagons or 60° rhombi (each two equilateral triangles). Kaleidohedra's two-way search for DICTO found exactly nine; this is one of the four that were new here.",
  'pv.detail.dictoSkewedEdCredit': "Found in Kaleidohedra by extending DICTO's skewed rhombic dodecahedron with a fifth edge direction, matched against Kaleidohedra's own equal-edge elongated-dodecahedron search.",
  'pv.detail.dogstarCredit': "The Dogstar is George W. Hart's stellation 8 of the dodecahedron (1996), which he noted fills space alternated with regular dodecahedra; Polyhedra-World also shows it. Hans Walser describes it too, as a cube with its six hip roofs cut away (his “semi-regular dodecahedron”), which fills space with regular dodecahedra like a 3D chessboard. DICTO named it the Dogstar, and a dodecahedron with 6 Dogstars on its faces a Sunstar.",
  'pv.detail.ekpLink': "Part of the Euclid–Kepler–Pacioli cell by DICTO, shown built, layer inside layer, in",
