  'pv.bridge.D20': "Vertex figure of the 600-cell {3,3,5}; a cell of the snub 24-cell.",
  'pv.bridge.D4': "Cell of the 5-cell {3,3,3}, 16-cell {3,3,4} and 600-cell {3,3,5}; vertex figure of the tesseract {4,3,3} and 120-cell {5,3,3}.",
  'pv.bridge.D8': "Cell of the 24-cell {3,4,3}; the equatorial slice of the 16-cell {3,3,4}, and its vertex figure.",
  'pv.bridge.DICTO_SKEWED_RD': "Oblique shadow of the tesseract {4,3,3}: its four blue-strut edge directions are the tesseract's four edge directions, projected at a slant. The regular RD is the straight-on shadow.",
  'pv.bridge.DODECAHEDRON': "Cell of the 120-cell {5,3,3}.",
