  'ss.prompt.taken': "そのセルはもう埋まっています。",
  'wiz.3d.stellaJewel': "DICTO ジュエルと星形八面体が市松模様に空間を埋めます。ジュエルだけをひし形の面どうしで並べることも。",
  'wiz.3d.djTetra': "四面体に並ぶ DICTO ジュエル 4 個、どの 2 個も面で接し、丸ごと置けます。星形八面体と組んで空間を埋めます。",
  'wiz.3d.djOcta': "星形八面体を囲む DICTO ジュエル 6 個、中心が燃える中身の詰まった立体。星形八面体と組んで空間を埋めます。",
  'wiz.3d.djOctet': "ジュエルを共有するクラスターをオクテットトラスのセルとして。どの星形八面体も八面体クラスターの中に：青い永遠の炎。",
  'wiz.3d.djKagome': "四面体クラスターがジュエル 1 個ずつを共有するカゴメ網。あいだの単独のジュエルは自動で埋まり、紫で示されます。",
  'wiz.3d.djHexa': "DICTO ヘキサ（DICTO ジュエル 8 個の立方体）をダイヤモンドの配置に並べたもの。各ヘキサは角のジュエル 4 個を隣と共有し、あいだのセルはすべて星形八面体が埋めます。",
  'wiz.3d.ssTetra': "セルの角を囲む正十二面体 4 個、丸ごと置けます。ドッグスターと組んで空間を埋めます。",
  'wiz.3d.ssOcta': "ドッグスターを囲む正十二面体 6 個、裏返しのサンスター、中心が燃えます。ドッグスターと組んで空間を埋めます。",
  'wiz.3d.ssOctet': "正十二面体クラスターをオクテットトラスのセルとして。どのドッグスターも八面体クラスターの中に：青い永遠の炎。",
  'wiz.3d.ssKagome': "上向きと下向きの正十二面体クラスターが 1 個ずつ共有するカゴメ網。そのあいだの単独のセルに紫の炎。",
