  'con.prompt.start': "オレンジのセルをタップして埋めましょう：正方形の最初の辺、X に沿って。",
  'con.prompt.junction': "接合点：{axis} が X に加わりました。角を曲がって続けましょう。",
  'con.prompt.hexagon': "六角形：{n} 個のセルから、3 方向で現れました。次はその周りにカゴメの星が育ちます。1 タップで辺 1 本。",
  'con.prompt.junctionXY': "接合点：XY、X と Y を合わせた方向。まだ 2D です。",
  'con.prompt.kagome': "カゴメの星：{n} 個のセルから現れました。3 方向の 6 本の線。周りにはカゴメ格子。タップを続けると Z が立ち上がりパイロクロアへ。",
  'con.prompt.tt': "切頂四面体：3D のカゴメの六角形、胴体です。六角形 4 つと三角形 4 つ。次は手足：各三角形に四面体、4 つとも 1 タップで。",
  'con.prompt.pyrochlore': "パイロクロア：{n} 個のセル。切頂四面体の各三角形に四面体がのり、1 つの大きな四面体に。3D+ のパイロクロアピースです。周りにはパイロクロア格子。 タップを続けると W が立ち上がりハイパーパイロクロアへ。",
  'con.prompt.t5': "切頂 5 胞体：4D の胴体。切頂四面体 5 つ（あなたのものも 1 つ）と四面体 5 つ。次は手足、5 つとも 1 タップで。",
  'con.prompt.hyper': "ハイパーパイロクロア：{n} 個のセル、1 つの大きな 5 胞体。切頂 5 胞体の各四面体に小さな 5 胞体。タップで W の方向に回転、もう一度タップで停止。",
  'con.prompt.startKagome': "オレンジのセルをタップして埋めましょう：六角形の最初の辺、X に沿って。",
  'con.prompt.startRd': "オレンジのセルをタップして埋めましょう：菱形の最初の辺、X に沿って。",
  'con.prompt.rhombus': "菱形：RD 自身の面、{n} 個のセル、70.53° と 109.47°。タップを続けると Z が立ち上がり RD へ、まず胴体から。",
  'con.prompt.rdBody': "立方体：RD の内側の胴体。その辺は菱形の短い対角線です。次は手足：各面に角錐、6 つとも 1 タップで。",
  'con.prompt.rd': "菱形十二面体：立方体と 6 つの角錐、12 枚の菱形、{n} 個のセル。周りには格子の 12 個の RD。 タップを続けると W が角を二つに分けます。",
  'con.prompt.rdTesseract': "テッセラクト：RD の立方体の角が W で二つに分かれた、4D の胴体。次は手足：6 つの頂点が 1 タップで両側とつながり、次の 1 タップで W 方向にもう 2 つ。",
  'con.prompt.cell24': "24 胞体：96 本の辺、RD の 4D の相棒。W 方向の影が RD です。タップで W の方向に回転、もう一度タップで停止。",
  'con.prompt.cube': "立方体：{n} 個のセルから現れました。今度は 4 番目の方向 W が角から内側へ伸びます：タップを続けてテッセラクトを作りましょう。",
  'con.prompt.tesseract': "テッセラクト：{n} 個のセルから現れました。タップで W の方向に回転し、もう一度タップで止まります。",
  'con.prompt.square': "正方形：{n} 個のセルから現れました。今度は角から Z が立ち上がります：タップを続けて立方体を作りましょう。",
  'con.prompt.edges': "ここからは、1 回のタップで残りの辺が 1 本ずつ埋まります。",
