  'wiz.3d.djTetra': "Cuatro DICTO Jewels en tetraedro, cada par cara con cara, colocados enteros; con stellas octangulas llenan el espacio.",
  'wiz.3d.djOcta': "Seis DICTO Jewels alrededor de una stella octangula, una pieza maciza que arde en su centro; con stellas llenan el espacio.",
  'wiz.3d.djOctet': "Los racimos que comparten Jewels como celdas de la celosía octeto, cada stella dentro de uno octaédrico: una llama eterna azul.",
