  'wiz.1d.construct': "Construye un cuadrado con celdas 1D, un toque cada vez, y luego elévalo a un cubo a lo largo de Z.",
  'wiz.1d.constructKagome': "Construye un hexágono con celdas 1D, luego la estrella de Kagome a su alrededor (seis líneas en tres direcciones) y después su red.",
  'wiz.1d.constructRd': "Construye el rombo propio del RD con celdas 1D y luego el dodecaedro rómbico: primero su cubo interior, después sus seis pirámides; luego su red.",
  'con.open': "Abrir en {dim}",
  'wiz.2d.nets': "Sigue la red fantasma de un sólido cara a cara y luego dóblala hasta formar el sólido.",
  'nets.prompt.start': "Sigue el desarrollo fantasma: toca para construir la primera cara, lado a lado.",
  'nets.prompt.faces': "Ahora cada toque construye la siguiente cara del desarrollo.",
  'nets.prompt.done': "{name}: el desarrollo está completo. Toca para plegarlo o arrastra el deslizador.",
  'nets.prompt.folded': "{name}: plegado a partir de su desarrollo. Arrastra el deslizador para desplegarlo.",
  'nets.fold': "Plegado: de plano a cerrado",
  'pack.spheres': "Spherical: cada pieza como una esfera; los RD enteros tocan a sus doce vecinos. El control deslizante cambia su tamaño. Solo una vista; tus celdas no cambian.",
  'pack.spheres@polyhedraverse': "Spherical: cada forma como una esfera de su mismo volumen, dentro de la forma. El control deslizante las dimensiona. Solo una vista; tus formas no cambian.",
  'pack.voids': "Huecos: los espacios que dejan las esferas, octaédricos (oro, seis esferas alrededor) y tetraédricos (rosa, cuatro alrededor), mostrados solo donde están del todo cerrados.",
  'pack.off': "Spherical: desactivado.",
  'pack.radius': "Tamaño de las esferas",
  'pack.none': "Coloca algunos RD enteros para ver los huecos entre ellos.",
