  'pack.spheres': "Spherical : chaque pièce en sphère ; les RD entiers touchent leurs douze voisins. Le curseur règle leur taille. Une vue seulement ; vos cellules ne changent pas.",
  'pack.spheres@polyhedraverse': "Spherical : chaque forme en sphère de même volume, à l'intérieur de la forme. Le curseur les dimensionne. Une vue seulement ; vos formes restent intactes.",
  'pack.voids': "Vides : les espaces que laissent les sphères, octaédriques (or, six sphères autour) et tétraédriques (rose, quatre autour), montrés seulement là où ils sont entièrement fermés.",
