  'nets.prompt.cell': "Cellule entière : {n} pièces pliées sur {total}. Touchez pour l'envelopper couche par couche, de l'intérieur vers l'extérieur ; faites glisser le curseur pour la déballer.",
  'nets.prompt.cellEmpty': "Rien n'est encore plié : commencez par les rectangles de Pacioli ; chaque pièce enveloppe ensuite la précédente.",
