  // ---- Kaleidohedra's own (joined 2026-10-08): its worlds' strings, and its versions of shared keys ----
  'wiz.3d.studies': "Un solide à la fois, construit exactement à partir de la cellule d'Euclide–Kepler–Pacioli : les fenêtres, leurs transformations et le dodécaèdre étiré. Cisaillez-les en copies ou en solide.",
  'shear.gap': "Bande rouge : ici la cellule ne remplit plus l'espace (son volume n'est pas celui de la maille). Cellule 0 le fait toujours.",
  'projection.label': 'Projection',
