  'kept.copy': "Copier l'ID",
  'kept.copied': "ID copié. Envoyez-le à DICTO pour le proposer au registre.",
  'kept.remove': "Retirer",
  'kept.removeAsk': "Retirer « {name} » de vos états gardés ?",
  'kept.check.same': "régénéré : le même objet",
  'kept.check.changed': "régénéré : le noyau fait maintenant un autre objet pour cet état (gardé avec krp-core {version})",
  'kept.check.unavailable': "cette version ne peut pas le régénérer",
  'studies.study': "Étude",
  'studies.windows': "Fenêtres : dodécaèdre moins six stellas",
  'studies.windowsStellas': "Fenêtres, avec les six stellas",
  'studies.checker': "Fenêtres et stellas, en damier",
  'studies.apart': "Écarter",
  'studies.note.checker': "La stella octangula est l'autre moitié des fenêtres : fenêtres dans les cellules paires, stellas dans les impaires, et chaque cube impair est sa stella plus les toits creusés de ses six voisins, sans vide ni chevauchement. Volumes 12 + 4 = deux cubes. Écartez-les pour les voir s'emboîter.",
  'studies.dogstar': "Dodécaèdres et leurs Dogstars",
  'studies.note.dogstar': "Les dodécaèdres réguliers des cellules paires (leur empilement en réseau le plus dense) laissent un trou dans chaque cellule impaire, et ce trou est exactement un Dogstar : une stellation partielle d'un dodécaèdre 1/φ³ fois plus petit (son cœur, les 12 pyramides, 24 des 30 coins et les 8 pointes dirigées vers les sommets du cube), à l'intérieur de la stella octangula de la cellule. Ses arêtes ne valent que 2/φ⁴, 2/φ³, 2/φ² et 2/φ. Dodécaèdres et Dogstars remplissent l'espace ; écartez-les pour le voir. Le Dogstar est la stellation 8 du dodécaèdre de George W. Hart (1996), qui a noté qu'il remplit l'espace en alternance avec des dodécaèdres réguliers ; Polyhedra-World le montre aussi. Hans Walser le décrit aussi, comme un cube privé de ses six toits en croupe (son « dodécaèdre semi-régulier »), qui remplit l'espace avec des dodécaèdres réguliers comme un échiquier en 3D.",
  'studies.stretch': "Dodécaèdre étiré",
  'studies.slider.stretch': "Étirer",
  'studies.shear.copies': "Cisaillement : copies sur le réseau",
  'studies.shear.solid': "Cisaillement : le solide lui-même",
  'studies.expanded': "Fenêtres rendues convexes (poussées vers l'extérieur)",
  'studies.push': "Poussée",
  'studies.note.expanded': "Chaque losange poussé droit vers l'extérieur, même taille et même angle ; l'enveloppe convexe. À la poussée dorée (0,727), les vides au-dessus des faces du cube deviennent 6 losanges d'or : 12 losanges épais, 6 losanges d'or, 8 triangles équilatéraux et 48 triangles.",
  'studies.icosido': "Des fenêtres à l'icosidodécaèdre",
  'studies.morph': "Métamorphose",
  'studies.note.icosido': "Chaque losange glisse le long de sa normale et dans son propre plan, en gardant sa taille et sa forme à 72°. À la fin, leur enveloppe est l'icosidodécaèdre (12 pentagones réguliers, 20 triangles équilatéraux) : chaque losange est dans un pentagone, qui est un losange à 72° plus un triangle d'or.",
  'studies.rdMorph': "Des fenêtres au dodécaèdre rhombique",
  'studies.note.rdMorph': "Chaque fenêtre garde son arête du cube (sa grande diagonale) et fait pivoter et s'allonger l'autre diagonale autour d'elle, en passant par des carrés, jusqu'à ce que les 12 se referment exactement en dodécaèdre rhombique, dont les losanges ont l'arête du cube pour petite diagonale.",
  'studies.note.windows': "12 losanges de 72° et 108°, chacun dans un plan de face du dodécaèdre, sur une arête du cube ; la partie creusée est faite de 48 triangles. Volume exactement 12.",
  'studies.note.windowsStellas': "12 losanges de 72° et 108°, chacun dans un plan de face du dodécaèdre, sur une arête du cube ; la partie creusée est faite de 48 triangles. Volume exactement 12.",
  'studies.note.stretch': "8 pentagones réguliers, 4 hexagones et 2 rectangles pour tout étirement ; des carrés à une arête (1,236) ; l'enveloppe de deux voisins par une face à 2.",
  'wiz.3d.targets': "Les 160 cellules cibles : toute cellule qui remplit l'espace, à arêtes toutes égales, dont les arêtes ne se rencontrent qu'à des angles particuliers. Choisissez-en une pour la voir seule, avec ses voisines par les faces, ou en bloc de son réseau.",
