  'pv.detail.bridges': "Ponts 3D+",
  'pv.detail.zomeCredit': "Trouvé par DICTO avec Zometool, construit avec des tiges bleues moyennes : chaque arête suit une des directions bleues de Zome.",
  'pv.detail.bainCredit': "Issu de l'étirement de Bain : étirez un réseau cubique centré de √2 le long d'un axe et il devient cubique à faces centrées. Ce sont les cellules de cet étirement dont toutes les arêtes sont égales, trouvées et vérifiées par DICTO dans Kaleidohedra. La forme du dodécaèdre rhombique était déjà connue, ainsi que le dodécaèdre allongé à hexagones réguliers (l'octaèdre tronqué privé d'une zone), auquel DICTO est arrivé indépendamment par cette nouvelle voie ; l'autre dodécaèdre allongé a été trouvé par DICTO.",
  'pv.detail.regularNineCredit': "L'un des Kaleidohedra Regular 9 : les seules formes qui pavent l'espace avec toutes les arêtes égales et des faces qui ne sont que des carrés, des hexagones réguliers ou des losanges de 60° (chacun deux triangles équilatéraux). La recherche dans les deux sens de Kaleidohedra pour DICTO en a trouvé exactement neuf ; celle-ci est l'une des quatre nouvelles ici.",
  'pv.detail.dictoSkewedEdCredit': "Trouvé dans Kaleidohedra en prolongeant le dodécaèdre rhombique incliné de DICTO par une cinquième direction d'arête, correspondant à la propre recherche de Kaleidohedra sur les dodécaèdres allongés à arêtes égales.",
  'pv.detail.dogstarCredit': "Le Dogstar est la stellation 8 du dodécaèdre de George W. Hart (1996), qui a noté qu'il remplit l'espace en alternance avec des dodécaèdres réguliers ; Polyhedra-World le montre aussi. Hans Walser le décrit aussi, comme un cube privé de ses six toits en croupe (son « dodécaèdre semi-régulier »), qui remplit l'espace avec des dodécaèdres réguliers comme un échiquier en 3D. DICTO l'a nommé Dogstar, et Sunstar un dodécaèdre portant 6 Dogstars sur ses faces.",
  'pv.detail.ekpLink': "Fait partie de la cellule Euclid–Kepler–Pacioli de DICTO, montrée construite, couche dans couche, dans",
  'pv.bridge.CUBE': "Cellule et section du tesseract {4,3,3} ; figure de sommet du 24-cell {3,4,3}.",
  'pv.bridge.CUBOCTAHEDRON': "Contour de l’ombre du 24-cell {3,4,3} vue par une cellule ; sa section équatoriale sur un axe incliné.",
  'pv.bridge.D20': "Figure de sommet du 600-cell {3,3,5} ; une cellule du snub 24-cell.",
  'pv.bridge.D4': "Cellule du 5-cell {3,3,3}, du 16-cell {3,3,4} et du 600-cell {3,3,5} ; figure de sommet du tesseract {4,3,3} et du 120-cell {5,3,3}.",
  'pv.bridge.D8': "Cellule du 24-cell {3,4,3} ; la section équatoriale du 16-cell {3,3,4}, et sa figure de sommet.",
  'pv.bridge.DICTO_SKEWED_RD': "Ombre oblique du tesseract {4,3,3} : ses quatre directions d'arêtes, en tiges bleues, sont les quatre du tesseract projetées en biais. Le RD régulier en est l'ombre de face.",
  'pv.bridge.DODECAHEDRON': "Cellule du 120-cell {5,3,3}.",
  'pv.bridge.GOLDEN_RHOMBOHEDRON_OBLATE': "Ombre d’une face 3D du 6-cube : une pièce du pavage de Penrose en 3D, le quasi-cristal icosaédrique 6D.",
  'pv.bridge.GOLDEN_RHOMBOHEDRON_PROLATE': "Ombre d’une face 3D du 6-cube : une pièce du pavage de Penrose en 3D, le quasi-cristal icosaédrique 6D.",
  'pv.bridge.J1_SQUARE_PYRAMID': "Cellule de la pyramide cubique dans l’empilement rhombique (tesseract + 8 pyramides cubiques = le 24-cell {3,4,3}) : deux se rejoignent en chacun de ses octaèdres. En 3D, six sur un cube forment le RD.",
  'pv.bridge.PENROSE_PRISM_THICK': "Le losange de Penrose épais (72°), ombre d’une face carrée du 5-cube, élevé d’une arête : une pièce du quasi-cristal décagonal 5D en couches.",
  'pv.bridge.PENROSE_PRISM_THIN': "Le losange de Penrose fin (36°), ombre d’une face carrée du 5-cube, élevé d’une arête : une pièce du quasi-cristal décagonal 5D en couches.",
