  'cat.zonohedraDesc': '타일링 자신의 조각으로 이루어진 도형으로, 나타나는 곳이면 어디서든 찾습니다.',
  'cat.polytopes': '폴리토프',
  'cat.polytopesDesc': '꼭짓점이 격자 위에 있는 고차원 폴리토프의 그림자로, 꼭짓점에 놓입니다. 조각을 막지 않고 타일링 위에 겹치며, 단면 안의 꼭짓점이 빛납니다.',
