  'con.prompt.junctionXY': "접합점: XY, X와 Y를 합친 방향. 여전히 2D입니다.",
  'con.prompt.kagome': "카고메 별: {n}개의 칸에서 나타났습니다. 세 방향의 여섯 선. 주위에는 카고메 격자. 계속 탭하면 Z가 솟아 파이로클로어로.",
  'con.prompt.tt': "깎은 사면체: 3D의 카고메 육각형, 몸통입니다. 육각형 넷, 삼각형 넷. 이제 팔다리: 각 삼각형 위에 사면체, 넷 모두 한 번 탭으로.",
  'con.prompt.pyrochlore': "파이로클로어: {n}개의 칸, 깎은 사면체의 각 삼각형에 사면체가 올라 하나의 큰 사면체. 3D+의 파이로클로어 조각입니다. 주위에는 파이로클로어 격자. 계속 탭하면 W가 솟아 하이퍼 파이로클로어로.",
  'con.prompt.t5': "깎은 5-포체: 4D의 몸통. 깎은 사면체 다섯(여러분의 것도 하나)과 사면체 다섯. 이제 팔다리, 다섯 모두 한 번 탭으로.",
  'con.prompt.hyper': "하이퍼 파이로클로어: {n}개의 칸, 하나의 큰 5-포체. 깎은 5-포체의 각 사면체에 작은 5-포체. 탭하면 W 방향으로 회전하고, 다시 탭하면 멈춥니다.",
  'con.prompt.startKagome': "주황색 칸을 탭해 채우세요: 육각형의 첫 변, X를 따라.",
  'con.prompt.startRd': "주황색 칸을 탭해 채우세요: 마름모의 첫 변, X를 따라.",
  'con.prompt.rhombus': "마름모: RD 자신의 면, {n}개의 칸, 70.53°와 109.47°. 계속 탭하면 Z가 솟아 RD로, 몸통부터.",
  'con.prompt.rdBody': "정육면체: RD 안쪽의 몸통. 그 모서리는 마름모의 짧은 대각선입니다. 이제 팔다리: 각 면에 피라미드, 여섯 모두 한 번 탭으로.",
  'con.prompt.rd': "마름모 십이면체: 정육면체와 여섯 피라미드, 마름모 열둘, {n}개의 칸. 주위에는 격자의 RD 열둘. 계속 탭하면 W가 모서리를 둘로 나눕니다.",
  'con.prompt.rdTesseract': "테서랙트: RD의 정육면체, 그 꼭짓점이 W로 둘로 나뉜 4D의 몸통. 이제 팔다리: 여섯 꼭짓점이 한 번 탭으로 양쪽과 이어지고, 다음 탭에 W 방향으로 둘 더.",
  'con.prompt.cell24': "24-포체: 모서리 96개, RD의 4D 짝. W 방향의 그림자가 RD입니다. 탭하면 W 방향으로 회전하고, 다시 탭하면 멈춥니다.",
  'con.prompt.cube': "정육면체: {n}개의 칸에서 나타났습니다. 이제 네 번째 방향 W가 모서리에서 안쪽으로 뻗습니다: 계속 탭해 테서랙트를 만드세요.",
  'con.prompt.tesseract': "테서랙트: {n}개의 칸에서 나타났습니다. 탭하면 W 방향으로 회전하고, 다시 탭하면 멈춥니다.",
  'con.prompt.square': "정사각형: {n}개의 칸에서 나타났습니다. 이제 모서리에서 Z가 솟아오릅니다: 계속 탭해 정육면체를 만드세요.",
  'con.prompt.edges': "이제 한 번 탭할 때마다 남은 모서리가 하나씩 채워집니다.",
  'con.prompt.parts': "이제 한 번 탭에 부분 하나가 통째로. 같은 모양의 부분은 함께 나타납니다.",
  'wiz.2d.kaleido': "독립된 월드: 펜로즈 마름모, 오각형, 삼각형, 육각형, 정사각형으로 만들면 거울이 만화경으로 바꿔 줍니다. 돌리고, 회전시키고, 흔들어 보세요.",
  'kal.ring': "고리",
  'kal.mirrors': "거울 {n}개",
  'kal.size': "크기 {n}",
  'kal.turn': "돌리기",
  'kal.shake': "흔들기",
  'kal.spin': "회전",
  'kal.safe': "안전",
  'kal.prompt.noFit': "그곳에는 {piece}을(를) 놓을 자리가 없습니다.",
  'kal.prompt.safe': "안전: 마름모는 펜로즈 맞춤 규칙이 허용하는 곳에만 놓이므로 언제나 진짜 펜로즈 타일링이 됩니다.",
  'hull.scale': '배율:',
