  'hull.info.removeShell': '{n}층 없애기',
  // ---- Kaleidohedra's own (joined 2026-10-08): its worlds' strings, and its versions of shared keys ----
  'wiz.3d.studies': "유클리드–케플러–파치올리 셀로 정확히 만든 입체를 하나씩: 창, 그 변형, 늘인 정십이면체. 복사본으로 또는 입체 자체로 밀어 보세요.",
  'shear.gap': "빨간 띠: 여기서는 셀이 공간을 채우지 않습니다(부피가 격자의 셀 부피와 다릅니다). 셀 0은 항상 채웁니다.",
  'projection.label': '투영',
