  'kept.keep': "보관",
  'kept.list': "보관함 ({n})",
  'kept.name': "이 상태의 이름(선택). 이 브라우저에만 보관됩니다: ID와 지문을 기록하고 열 때 다시 생성합니다.",
  'kept.done': "이 브라우저에 보관했습니다.",
