  'kept.copy': "ID 복사",
  'kept.copied': "ID를 복사했습니다. 기록에 추가를 제안하려면 DICTO에게 보내세요.",
  'kept.remove': "삭제",
  'kept.removeAsk': "보관함에서 \"{name}\"을(를) 삭제할까요?",
  'kept.check.same': "다시 생성: 같은 형태",
  'kept.check.changed': "다시 생성: 코어가 이제 이 상태에서 다른 형태를 만듭니다 (krp-core {version}로 보관)",
  'kept.check.unavailable': "이 버전으로는 다시 생성할 수 없습니다",
  'studies.study': "스터디",
  'studies.windows': "창: 십이면체에서 스텔라 여섯 개를 뺀 것",
  'studies.windowsStellas': "창과 스텔라 여섯 개",
  'studies.checker': "창과 스텔라, 체크무늬",
  'studies.apart': "떼어 놓기",
  'studies.note.checker': "스텔라 옥탕굴라는 창의 나머지 반쪽입니다: 짝수 셀에는 창, 홀수 셀에는 스텔라. 홀수 정육면체는 모두 자기 스텔라와 이웃 여섯 셀의 깎인 지붕으로 빈틈도 겹침도 없이 채워집니다. 부피 12 + 4 = 정육면체 두 개. 떼어 놓고 맞물리는 모습을 보세요.",
  'studies.dogstar': "정십이면체와 도그스타",
  'studies.note.dogstar': "짝수 셀의 정십이면체(가장 조밀한 격자 채움)는 홀수 셀마다 구멍 하나를 남깁니다. 그 구멍은 정확히 도그스타입니다: 크기 1/φ³인 십이면체의 부분 별모양(핵, 피라미드 12개 모두, 쐐기 30개 중 24개, 정육면체 꼭짓점을 가리키는 가시 8개)으로, 그 셀의 스텔라 옥탕굴라 안에 있습니다. 모서리는 2/φ⁴, 2/φ³, 2/φ², 2/φ뿐입니다. 십이면체와 도그스타가 공간을 채웁니다. 떼어 놓고 보세요. 도그스타는 George W. Hart의 십이면체 별모양 8번(1996)으로, Hart는 정십이면체와 번갈아 놓으면 공간을 채운다고 적었습니다. Polyhedra-World에도 실려 있습니다. Hans Walser도 정육면체에서 모임지붕 6개를 떼어 낸 모양(그가 말하는 '준정십이면체')으로 설명하며, 정십이면체와 함께 3D 체스판처럼 공간을 채웁니다.",
  'studies.stretch': "늘린 십이면체",
  'studies.slider.stretch': "늘이기",
  'studies.shear.copies': "시어: 격자 위의 복사본",
  'studies.shear.solid': "시어: 입체 자체",
  'studies.expanded': "볼록하게 만든 창 (밖으로 밀어냄)",
  'studies.push': "밀기",
  'studies.note.expanded': "각 마름모를 크기와 각도 그대로 바깥으로 밀어내고 볼록 껍질을 취합니다. 황금 밀기(0.727)에서 정육면체 면 위의 틈이 평평해져 황금 마름모 6개가 됩니다: 두꺼운 마름모 12, 황금 마름모 6, 정삼각형 8, 삼각형 48.",
  'studies.icosido': "창에서 십이이십면체로",
  'studies.morph': "변형",
  'studies.note.icosido': "각 마름모가 크기와 72° 모양을 그대로 유지한 채 법선 방향과 자기 평면 안에서 미끄러집니다. 마지막에 볼록 껍질은 십이이십면체(정오각형 12, 정삼각형 20)가 되고, 각 마름모는 오각형 안에 놓입니다. 오각형은 72° 마름모와 황금 삼각형으로 이루어집니다.",
  'studies.rdMorph': "창에서 마름모십이면체로",
  'studies.note.rdMorph': "각 창은 정육면체 모서리(긴 대각선)를 유지한 채 다른 대각선을 그 둘레로 돌리며 늘입니다. 정사각형을 거쳐 12개가 정확히 닫혀 마름모십이면체가 되며, 그 마름모에서는 정육면체 모서리가 짧은 대각선입니다.",
  'studies.note.windows': "72°와 108°의 마름모 12개가 각각 십이면체 자신의 면 평면, 정육면체 모서리 위에 있습니다. 깎인 부분은 삼각형 48개. 부피는 정확히 12.",
  'studies.note.windowsStellas': "72°와 108°의 마름모 12개가 각각 십이면체 자신의 면 평면, 정육면체 모서리 위에 있습니다. 깎인 부분은 삼각형 48개. 부피는 정확히 12.",
  'studies.note.stretch': "얼마나 늘려도 정오각형 8개, 육각형 4개, 직사각형 2개. 모서리 하나(1.236)에서 정사각형, 2에서 면으로 이웃한 두 개의 볼록 껍질.",
  'wiz.3d.targets': "160개의 목표 셀: 모든 모서리 길이가 같고 모서리가 특별한 각도에서만 만나는 공간 채움 셀. 하나를 골라 단독으로, 면으로 이웃한 셀과 함께, 또는 격자의 블록으로 보세요.",
