  'welcome.aboutTitle@kaleidohedra': "Kaleidohedra 정보",
  'welcome.overview@kaleidohedra': "결정 격자 위에 조립한 뒤 격자를 밀어 보세요. 모든 조각이 격자와 함께 움직입니다.",
  'welcome.aboutTitle@polyhedraverse': "Polyhedraverse 정보",
  'welcome.overview@polyhedraverse': "초상화 갤러리: {n}개의 도형을 가까이에서 — 면과 면, 꼭짓점과 꼭짓점으로 연결해 보세요.",
  'wiz.dim.2D@kaleidohedra': "전개도: 입체의 전개도를 평평하게 만든 뒤 접어서 3D로 만듭니다.",
  'wiz.dim.3D@kaleidohedra': "시어가 움직이는 모든 격자와 Euclid–Kepler–Pacioli 셀, Targets, Shells, Golden Rhombohedra.",
  'wiz.dim.3D@polyhedraverse': "가족별 모든 도형을 하나씩 가까이에서: 플라톤 다면체부터 존슨 다면체, 별모양, 공간을 채우는 짝, DICTO의 조각까지.",
