  'ss.prompt.hole': "这一面通向一个隐藏的部件；切换视图才能放置。",
  'ss.prompt.taken': "这个晶胞已经填好了。",
  'wiz.3d.stellaJewel': "DICTO 宝石与星形八面体以棋盘方式填满空间，或只用宝石，以菱形面相贴。",
  'wiz.3d.djTetra': "4 个 DICTO 宝石排成四面体，两两面对面相接，整体放置；与星形八面体一起填满空间。",
  'wiz.3d.djOcta': "6 个 DICTO 宝石围住一个星形八面体，中心燃烧的实心整体；与星形八面体一起填满空间。",
  'wiz.3d.djOctet': "共享宝石的簇作为八隅桁架的胞，每个星形八面体都在一个八面体簇中：蓝色的永恒之火。",
  'wiz.3d.djKagome': "四面体簇共享单个宝石，Kagome 式；它们之间的单个宝石会自动填入，呈紫色。",
  'wiz.3d.djHexa': "DICTO Hexa（八个 DICTO 宝石组成的立方体）按金刚石图案排列：每个与相邻的共享四个角宝石，星形八面体填满它们之间的每个格子。",
  'wiz.3d.ssTetra': "围绕格角的 4 个正十二面体，整体放置；与犬星一起填满空间。",
  'wiz.3d.ssOcta': "6 个正十二面体围住一个犬星，里外翻转的 Sunstar，中心燃烧；与犬星一起填满空间。",
  'wiz.3d.ssOctet': "正十二面体簇作为八隅桁架的胞，每个犬星都在一个八面体簇中：蓝色的永恒之火。",
  'wiz.3d.ssKagome': "朝上与朝下的正十二面体簇共享单个十二面体，Kagome 式；它们之间每个单独的格子里有紫色火焰。",
  'dj.view': "视图",
