  'dj.view.hullCuboHollow': "立方八面体 Kagome 网络（空心）",
  'dj.view.hullRhombo': "菱面体 Kagome 网络（每个部件都属于两个簇）",
  'dj.view.hullOcta': "八面体 Kagome 网络（钙钛矿网络）",
  'dj.view.hexa': "DICTO Hexa 金刚石网络（共享角宝石的 Hexa）",
  'dj.view.hexaKey': "DICTO Hexa 与 Hexa-Key 棋盘（窗对窗，5 : 3）",
  'dj.prompt.single': "那个格子放的是簇之间单独的一个 DICTO 宝石。",
  'dj.view.chain': "宝石链（立方体、星形八面体、Dogstar、十二面体 ×1/φ³、DICTO 宝石 ×1/φ³）",
  'dj.count': "{even} 个 DICTO 宝石，{odd} 个星形八面体",
