  'dj.prompt.taken': "这个晶胞已经填好了。",
  'wiz.4d.z4': '超立方体（4D 立方体）位于每个整数坐标点上。它在 w = 0 处的截面就是 RD 世界的单位立方体。',
  'wiz.4d.d4': '24 胞体，即 4D 的 RD：它在 w = 0 处的截面就是 FCC 世界。底部的按钮可切换为放置 16 胞体。',
  'wiz.4d.a4': 'A4 晶格上共享顶点的 5 胞体，它的 Pyrochlore 截面正是 Pyrochlore 世界。放置截角 5 胞体，它们的 5 胞体会自动出现。底部的按钮可切换为双截角 5 胞体或单个 5 胞体。',
  'hull.label': '外壳：',
  'hull.steps': '步数（截半立方体）',
  'hull.distance': '距离（球）',
  'hull.tetrahedron': '正四面体',
  'hull.tetrahedronMirror': '正四面体（镜像）',
