  'con.prompt.junctionXY': "Узел: XY — X и Y вместе; всё ещё 2D.",
  'con.prompt.kagome': "Звезда кагоме: она возникла из {n} клеток, шесть линий в трёх направлениях. Вокруг — решётка кагоме. Нажимайте дальше: Z поднимается в пирохлор.",
  'con.prompt.tt': "Усечённый тетраэдр: шестиугольник кагоме в 3D, тело: четыре шестиугольника, четыре треугольника. Теперь конечности: тетраэдр на каждом треугольнике, все четыре одним касанием.",
  'con.prompt.pyrochlore': "Пирохлор: {n} клеток, усечённый тетраэдр с тетраэдром на каждом треугольнике: один большой тетраэдр, деталь «Пирохлор» в 3D+. Вокруг — решётка пирохлора. Нажимайте дальше: W поднимается в гиперпирохлор.",
  'con.prompt.t5': "Усечённая 5-ячейка: тело в 4D, пять усечённых тетраэдров (ваш — один из них) и пять тетраэдров. Теперь конечности, все пять одним касанием.",
  'con.prompt.hyper': "Гиперпирохлор: {n} клеток, одна большая 5-ячейка — усечённая 5-ячейка с малой 5-ячейкой на каждом тетраэдре. Нажмите, чтобы вращать её через W; нажмите ещё раз, чтобы остановить.",
  'con.prompt.startKagome': "Нажмите, чтобы заполнить оранжевую клетку: первая сторона шестиугольника, вдоль X.",
  'con.prompt.startRd': "Нажмите, чтобы заполнить оранжевую клетку: первая сторона ромба, вдоль X.",
  'con.prompt.rhombus': "Ромб: собственная грань RD, {n} клеток, 70,53° и 109,47°. Нажимайте дальше: Z поднимается в RD, сначала тело.",
  'con.prompt.rdBody': "Куб: тело RD, внутри него; его рёбра — короткие диагонали ромбов. Теперь конечности: пирамида на каждой грани, все шесть одним касанием.",
  'con.prompt.rd': "Ромбододекаэдр: куб с шестью пирамидами, двенадцать ромбов, {n} клеток. Вокруг — двенадцать RD его решётки. Нажимайте дальше: W разводит его углы.",
  'con.prompt.rdTesseract': "Тессеракт: куб RD, его углы разведены по W, — тело в 4D. Теперь конечности: шесть вершин одним касанием соединяются с обеими сторонами, ещё две вдоль W — другим.",
  'con.prompt.cell24': "24-ячейка: 96 рёбер, 4D-собрат RD; её тень вдоль W — это RD. Нажмите, чтобы вращать её через W; нажмите ещё раз, чтобы остановить.",
  'con.prompt.cube': "Куб: он возник из {n} клеток. Теперь из угла внутрь уходит W, четвёртое направление: продолжайте нажимать, чтобы построить тессеракт.",
  'con.prompt.tesseract': "Тессеракт: он возник из {n} клеток. Нажмите, чтобы вращать его через W; нажмите ещё раз, чтобы остановить.",
  'con.prompt.square': "Квадрат: он возник из {n} клеток. Теперь из угла поднимается Z: продолжайте нажимать, чтобы построить куб.",
  'con.prompt.edges': "Теперь каждое нажатие заполняет одно оставшееся ребро.",
  'con.prompt.parts': "Теперь каждое касание добавляет целую часть; одинаковые части появляются вместе.",
  'wiz.2d.kaleido': "Отдельный мир: стройте из ромбов Пенроуза, пятиугольников, треугольников, шестиугольников и квадратов, а зеркала превращают это в калейдоскоп. Поворачивайте, вращайте, встряхивайте.",
  'kal.ring': "Кольцо",
  'kal.mirrors': "Зеркал: {n}",
  'kal.size': "Размер {n}",
