  'kal.shake': "Встряхнуть",
  'kal.spin': "Вращать",
  'kal.safe': "Надёжно",
  'kal.prompt.noFit': "Там нет места для фигуры «{piece}».",
  'kal.prompt.safe': "Надёжно: ромбы встают только туда, где это позволяет правило стыковки Пенроуза, поэтому всегда получается настоящая мозаика Пенроуза.",
  'hull.scale': 'Масштаб:',
  'hull.merge': 'Объединить ×{k}',
