  'welcome.aboutTitle@kaleidohedra': "О Kaleidohedra",
  'welcome.overview@kaleidohedra': "Стройте на кристаллических решётках, а затем сдвигайте их: каждая деталь движется вместе с решёткой.",
  'welcome.aboutTitle@polyhedraverse': "О Polyhedraverse",
  'welcome.overview@polyhedraverse': "Портретная галерея: {n} фигур крупным планом — соединяйте их грань к грани, вершина к вершине.",
  'wiz.dim.2D@kaleidohedra': "Развёртки: соберите развёртку тела на плоскости, затем сложите её в 3D.",
  'wiz.dim.3D@kaleidohedra': "Все решётки, которые сдвигает Shear, а также ячейка Euclid–Kepler–Pacioli, Targets, Shells и Golden Rhombohedra.",
  'wiz.dim.3D@polyhedraverse': "Все формы по семействам, по одной, вблизи: от платоновых тел до многогранников Джонсона, звёздчатые формы, пары, заполняющие пространство, и детали DICTO.",
  'wiz.dimAll.2D': "Плоские мозаики и Калейдоскоп, а также развёртки, которые складываются в тела.",
