  'poly.d.extend4d': "Продолжить в 4D",
  'poly.d.prism4dNote': "Её 4D-призма как 3D-тень: фигура, копия на шаг вдоль четвёртого измерения и призматическая ячейка между каждой парой граней. Перетащите, чтобы вращать.",
  'poly.d.extend4dNote': "Весь 4D-многогранник, ячейкой которого служит эта фигура, все ячейки в перспективе: внутренние тёплые и плотные, внешние бледные. Перетащите, чтобы вращать.",
