  'poly.rcp.coords': "Координаты RCP",
  'poly.noRoom': "Здесь нет места: как ни поставь, деталь пройдёт сквозь уже поставленную.",
  'poly.hints': "Подсказки",
  'poly.hints.title': "Что дальше: призраки там, где встанут следующие детали, и грани, которых они касаются, светятся их цветом. Коснитесь, чтобы поставить.",
  'poly.star.wireframe': "Каркас",
  'poly.star.translucent': "Полупрозрачный",
