  'pv.parallelohedra.section.fedorov': "Пять Фёдорова",
  'pv.parallelohedra.section.variants': "Варианты",
  'pv.parallelohedra.section.kaleidohedra': "Проверено в Kaleidohedra",
  'pv.parallelohedra.section.regularNine': "Kaleidohedra Regular 9",
  'pv.bridges.section.cells': "Ячейки",
  'pv.bridges.section.shadows': "Тени",
  'pv.bridges.section.slices': "Сечения",
  'pv.bridges.section.corners': "Вершины",
  'pv.detail.bridges': "3D+ мосты",
  'pv.detail.zomeCredit': "Найдено DICTO в Zometool, собрано из средних синих стержней: каждое ребро идёт по одному из синих направлений Zome.",
  'pv.detail.bainCredit': "Из растяжения Бейна: растяните объёмноцентрированную кубическую решётку в √2 раз вдоль одной оси, и она станет гранецентрированной. Это ячейки этого растяжения со всеми равными рёбрами, найденные и проверенные DICTO в Kaleidohedra. Форма ромбического додекаэдра уже была известна, как и удлинённый додекаэдр с правильными шестиугольниками (усечённый октаэдр без одной зоны), к которому DICTO независимо пришёл этим новым путём; другой удлинённый додекаэдр нашёл DICTO.",
  'pv.detail.regularNineCredit': "Одна из Kaleidohedra Regular 9: единственные фигуры, заполняющие пространство, у которых все рёбра равны, а грани — только квадраты, правильные шестиугольники или ромбы 60° (каждый из двух правильных треугольников). Двусторонний поиск Kaleidohedra для DICTO нашёл ровно девять; это одна из четырёх, новых здесь.",
  'pv.detail.dictoSkewedEdCredit': "Найдено в Kaleidohedra путём добавления пятого направления ребра к скошенному ромбододекаэдру DICTO, совпадающего с собственным поиском Kaleidohedra равнорёберных удлинённых додекаэдров.",
  'pv.detail.dogstarCredit': "Звезда-пёс — это звёздчатая форма додекаэдра № 8 Джорджа Харта (1996); Харт отметил, что она заполняет пространство, чередуясь с правильными додекаэдрами. Она есть и на Polyhedra-World. Ханс Вальзер (Hans Walser) тоже описывает её — как куб со срезанными шестью вальмовыми крышами (его «полуправильный додекаэдр»), который вместе с правильными додекаэдрами заполняет пространство, как трёхмерная шахматная доска. DICTO назвал её Dogstar, а додекаэдр с 6 такими звёздами на гранях — Sunstar.",
