const I18N = { en, ja, es, fr, ko, zh, ru };

/**
 * Looks up `key` in the given language's dictionary, falling back to
 * English, then the raw key -- same fallback chain as Polyhedraverse's
 * own t(). `vars` does simple `{name}` substitution; HTML-bearing
 * values (e.g. lab.rhombisLinkHint) are meant to be assigned via
 * innerHTML at the call site, matching how this codebase already
 * builds its own dynamic markup (see welcome.js's overlayHtml()).
 */
export function t(key, lang, vars) {
  // A key can have a version for one site, `key@site` (e.g. its About title); that comes first.
  const own = `${key}@${SITE}`;
  let s = I18N[lang]?.[own] ?? I18N.en[own] ?? I18N[lang]?.[key] ?? I18N.en[key] ?? key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, String(v));
  }
  return s;
}

/**
 * Counted phrases: `key.one` when n is 1, else `key.other`, with {n}
 * filled in. Languages without plurals give both the same text.
 */
/** t() for a given app rather than the front door: `key@<site>` first (the DICTO wizard shows
 *  each app's own texts while you browse it). */
export function tFor(site, key, lang, vars) {
  const own = `${key}@${site}`;
  let s = I18N[lang]?.[own] ?? I18N.en[own] ?? I18N[lang]?.[key] ?? I18N.en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, String(v));
  return s;
}

export function tn(key, lang, n, vars) {
  return t(`${key}.${n === 1 ? 'one' : 'other'}`, lang, { n, ...vars });
}

export { I18N as __I18N_FOR_VERIFY_ONLY__ };
